@page "/"

<PageTitle>Recipe Community</PageTitle>

<h1 class="mb-4">🍳 Recipe Community</h1>
<p class="lead">Discover and share delicious recipes with our community.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in Categories)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@category.Icon @category.Name</h5>
                    <p class="card-text">@category.Description</p>
                    <a href="@($"category/{category.Slug}")" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private record CategoryInfo(string Name, string Slug, string Icon, string Description);

    private static readonly CategoryInfo[] Categories =
    [
        new("Breakfast", "breakfast", "🥞", "Start your day with these morning favorites."),
        new("Main Courses", "main-courses", "🍖", "Hearty meals for lunch and dinner."),
        new("Desserts", "desserts", "🍰", "Sweet treats to satisfy your cravings."),
        new("Vegetarian", "vegetarian", "🥗", "Delicious meat-free dishes."),
        new("Quick & Easy", "quick-easy", "⚡", "Ready in 30 minutes or less."),
        new("Soups & Stews", "soups-stews", "🍲", "Warm and comforting bowls.")
    ];
}

