@page "/category/{Slug}"

<PageTitle>@GetCategoryName() — Recipe Community</PageTitle>

<h1>@GetCategoryIcon() @GetCategoryName()</h1>
<p class="lead">@GetCategoryDescription()</p>

<div class="row mt-3">
    @foreach (var recipe in GetRecipes())
    {
        <div class="col-md-6 mb-3">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <p class="card-text text-muted">@recipe.Summary</p>
                    <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

<a href="/" class="btn btn-link mt-3">← Back to Categories</a>

@code {
    [Parameter] public string Slug { get; set; } = "";

    private record RecipeInfo(int Id, string Title, string Summary);

    private string GetCategoryName() => Slug switch
    {
        "breakfast" => "Breakfast",
        "main-courses" => "Main Courses",
        "desserts" => "Desserts",
        "vegetarian" => "Vegetarian",
        "quick-easy" => "Quick & Easy",
        "soups-stews" => "Soups & Stews",
        _ => "Recipes"
    };

    private string GetCategoryIcon() => Slug switch
    {
        "breakfast" => "🥞",
        "main-courses" => "🍖",
        "desserts" => "🍰",
        "vegetarian" => "🥗",
        "quick-easy" => "⚡",
        "soups-stews" => "🍲",
        _ => "📖"
    };

    private string GetCategoryDescription() => Slug switch
    {
        "breakfast" => "Start your day with these morning favorites.",
        "main-courses" => "Hearty meals for lunch and dinner.",
        "desserts" => "Sweet treats to satisfy your cravings.",
        "vegetarian" => "Delicious meat-free dishes.",
        "quick-easy" => "Ready in 30 minutes or less.",
        "soups-stews" => "Warm and comforting bowls.",
        _ => ""
    };

    private RecipeInfo[] GetRecipes() => Slug switch
    {
        "breakfast" => [
            new(1, "Classic Pancakes", "Fluffy buttermilk pancakes with maple syrup."),
            new(2, "Avocado Toast", "Creamy avocado on sourdough with everything seasoning.")
        ],
        "main-courses" => [
            new(3, "Grilled Chicken Parmesan", "Crispy breaded chicken with marinara and melted mozzarella."),
            new(4, "Beef Stir Fry", "Tender beef strips with colorful vegetables in savory sauce.")
        ],
        "desserts" => [
            new(5, "Chocolate Lava Cake", "Rich molten chocolate center with a delicate cake shell."),
            new(6, "Tiramisu", "Classic Italian dessert with coffee-soaked ladyfingers.")
        ],
        "vegetarian" => [
            new(7, "Mushroom Risotto", "Creamy arborio rice with wild mushrooms and parmesan."),
            new(8, "Veggie Buddha Bowl", "Quinoa, roasted vegetables, and tahini dressing.")
        ],
        "quick-easy" => [
            new(9, "15-Minute Pasta", "Garlic butter pasta with fresh herbs and parmesan."),
            new(10, "Caprese Sandwich", "Fresh mozzarella, tomato, and basil on ciabatta.")
        ],
        "soups-stews" => [
            new(11, "Tomato Basil Soup", "Velvety smooth tomato soup with fresh basil."),
            new(12, "Beef Chili", "Hearty chili loaded with beans and spices.")
        ],
        _ => []
    };
}

@rendermode InteractiveServer

<div class="star-rating d-inline-block" role="group" aria-label="Rate this recipe">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button type="button"
                class="btn btn-link fs-3 p-0 text-decoration-none"
                @onclick="() => SetRating(star)"
                aria-label="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
            @(star <= CurrentRating ? "★" : "☆")
        </button>
    }
    @if (CurrentRating > 0)
    {
        <span class="ms-2 text-muted">You rated this @CurrentRating/5</span>
    }
</div>

@code {
    private int CurrentRating { get; set; }

    private void SetRating(int rating)
    {
        CurrentRating = rating;
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe — Recipe Community</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="lead">Share your favorite recipe with the community.</p>

@if (IsSubmitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@Model.Title</strong>" with the community.</p>
        <button class="btn btn-outline-success" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => Model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Model.Ingredients"
                           placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples" />
            <ValidationMessage For="() => Model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Model.Steps"
                           placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Roll out dough." />
            <ValidationMessage For="() => Model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

<a href="/" class="btn btn-link mt-3">← Back to Home</a>

@code {
    private RecipeSubmission Model { get; set; } = new();
    private bool IsSubmitted { get; set; }

    private void HandleSubmit()
    {
        IsSubmitted = true;
    }

    private void Reset()
    {
        Model = new();
        IsSubmitted = false;
    }

    private class RecipeSubmission
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the preparation steps.")]
        public string Steps { get; set; } = "";
    }
}

